# A simplified container concept
class Container:
    def __init__(self):
        self.registry = {}

    def register(self, name, factory):
        self.registry[name] = factory

    def resolve(self, name):
        return self.registry[name](self)

container = Container()
container.register("emailer", lambda c: SmtpEmailer())
container.register("generator", lambda c: ReportGenerator(c.resolve("emailer")))

generator = container.resolve("generator")

